const s = ($input.first().json.output) || {};
return [{
  json: {
    event: s.event || {},
    audience: s.audience || {},
    unknowns: Array.isArray(s.unknowns) ? s.unknowns : [],
  }
}];

const scout = $("Prepare Demand Input").first().json;
const demand = ($input.first().json.output) || {};
return [{
  json: {
    event: scout.event || {},
    audience: scout.audience || {},
    demand,
  }
}];

const event = $("Prepare Deal Input").first().json.event || {};
const out = ($input.first().json.output) || {};
const opportunities = Array.isArray(out.opportunities) ? out.opportunities : [];
const claims = [];
for (const o of opportunities) {
  if (!o || !o.company) continue;
  claims.push({ claim: o.company + " is a company operating in the " + (o.industry || "relevant") + " industry", basis: "deal_hunter", company: o.company });
  if (Array.isArray(o.evidence)) {
    for (const e of o.evidence) {
      if (e && e.claim) claims.push({ claim: e.claim, basis: e.basis || "deal_hunter", company: o.company });
    }
  }
}
return [{ json: { event, claims: claims.slice(0, 8), opportunities } }];

const prev = $("Collect Claims").first().json;
const verification = ($input.first().json.output) || {};
return [{
  json: {
    event: prev.event || {},
    opportunities: Array.isArray(prev.opportunities) ? prev.opportunities : [],
    verification,
  }
}];

const prev = $("Prepare Money Input").first().json;
const money = $input.first().json || {};
return [{
  json: {
    event: prev.event || {},
    opportunities: Array.isArray(prev.opportunities) ? prev.opportunities : [],
    verification: prev.verification || {},
    financial_analysis: Array.isArray(money.financial_analysis) ? money.financial_analysis : [],
  }
}];

const getOut = (name) => {
  const j = $(name).first().json || {};
  return j.output || j;
};

const scout = getOut("Execute Event Scout");
const demand = getOut("Execute Demand Analyst");
const dealOut = getOut("Execute Deal Hunter");
const verification = getOut("Execute Verifier");
const money = getOut("Execute Money Analyst");
const partnerOut = $input.first().json?.output || $input.first().json || {};

const partners = Array.isArray(partnerOut.partners) ? partnerOut.partners : [];
const opportunities = Array.isArray(dealOut.opportunities) ? dealOut.opportunities : [];
const vSummary = verification.summary || {};
const portfolio = money.portfolio || {};
const currency = money.currency || "INR";

const nums = [scout.confidence, demand.confidence, vSummary.overall_confidence].filter(n => typeof n === "number");
const overall_confidence = nums.length ? Number((nums.reduce((a,b)=>a+b,0)/nums.length).toFixed(2)) : 0.85;

const recommendations = partners.slice(0, 5).map(p => ({
  rank: p.rank,
  company: p.company,
  rank_score: p.rank_score,
  expected_profit: p.expected_profit,
  currency: p.currency || currency,
  action: "Prepare outreach for " + p.company,
  rationale: p.rationale,
}));

const actions = recommendations.map(r => ({
  type: "contact_company",
  target: r.company,
  requires_approval: true,
  status: "pending_approval",
}));

const report = {
  event: scout.event || {},
  audience: scout.audience || demand.audience_analysis || {},
  research: { scout_fields: scout.fields || [], unknowns: scout.unknowns || [] },
  demand_analysis: demand,
  opportunities,
  verification: verification.verifications || [],
  verification_summary: vSummary,
  financial_analysis: money.financial_analysis || [],
  portfolio,
  partners,
  recommendations,
  actions,
  risks: [
    ...(vSummary.unverified_or_worse ? ["Some partner claims are UNVERIFIED (" + vSummary.unverified_or_worse + ") — treat estimates cautiously."] : []),
    ...(scout.unknowns && scout.unknowns.length ? ["Missing event details: " + scout.unknowns.join("; ")] : []),
  ],
  confidence: overall_confidence,
  metadata: {
    generated_at: new Date().toISOString(),
    currency,
    partners_ranked: partners.length,
    opportunities_found: opportunities.length,
  },
};

const eventName = (scout.event && (scout.event.name || scout.event.title)) ? (scout.event.name || scout.event.title) : "DevCon 2025";
let msg = "🎯 EVENT MONEY AGENT — Autonomous Report Completed\n\n";
msg += "📌 Event: " + eventName + "\n";
msg += "⭐ Overall Confidence: " + overall_confidence + "\n";
msg += "💼 Opportunities Found: " + opportunities.length + "\n";
msg += "📊 Partners Ranked: " + partners.length + "\n";
msg += "💰 Total Expected Profit: " + currency + " " + (portfolio.total_expected_profit || 0).toLocaleString() + "\n\n";
msg += "🏆 Top Recommendations:\n";
recommendations.forEach(r => {
  msg += r.rank + ". " + r.company + " (Score: " + r.rank_score + " | Exp. Profit: " + (r.currency||currency) + " " + (r.expected_profit||0).toLocaleString() + ")\n";
});
if (report.risks.length) { msg += "\n⚠️ Risks:\n- " + report.risks.join("\n- ") + "\n"; }

return [{ json: { report, telegram_summary: msg } }];

const report = $("Assemble Final Report").first().json.report;
const summary = $("Assemble Final Report").first().json.telegram_summary;
const humanInput = $input.first().json || {};
const isApproved = humanInput.data?.approved ?? humanInput.approved;
let decision = "AUTO_READY";
if (isApproved === true) {
  decision = "APPROVE";
} else if (isApproved === false) {
  decision = "REJECT";
} else if (humanInput.Decision || humanInput.decision) {
  decision = humanInput.Decision || humanInput.decision;
}
const responderName = humanInput.data?.responder?.name || humanInput.data?.responder?.username || "Telegram User";
const notes = humanInput["Notes (optional)"] || humanInput.notes || (isApproved === true ? ("Approved via Telegram by " + responderName) : (isApproved === false ? ("Rejected via Telegram by " + responderName) : "Report generated autonomously."));

return [{
  json: {
    status: isApproved === true ? "APPROVED" : (isApproved === false ? "REJECTED" : "COMPLETED"),
    decision,
    notes,
    summary,
    final_report: report
  }
}];
